<?php
namespace App\Http\Controllers;use App\Contracts\ProtectedMediaStorage;use App\Jobs\GenerateMediaExport;use App\Models\{Group,MediaExport,Photo};use App\Services\Media\CloudFrontUrlSigner;use Illuminate\Http\Request;use Illuminate\Support\Facades\{Gate,Storage};use Illuminate\Support\Str;
class MediaExportController extends Controller {private function reply(Request$r,array$data,int$status=200){return$r->header('X-Inertia')?redirect()->back(303):response()->json($data,$status);}public function store(Request$r,Group$group){Gate::authorize('view',$group);$ids=array_values(array_unique($r->validate(['photo_ids'=>'required|array|max:500','photo_ids.*'=>'integer'])['photo_ids']));$photos=Photo::where('group_id',$group->id)->whereIn('id',$ids)->get();abort_unless($photos->count()===count($ids),422,'Every selected photo must belong to this group.');$authorized=[];foreach($photos as$p)if(Gate::forUser($r->user())->allows('download',$p))$authorized[]=$p->id;abort_unless(count($authorized)===count($ids),403);$export=MediaExport::create(['uuid'=>(string)Str::uuid(),'group_id'=>$group->id,'user_id'=>$r->user()->id,'state'=>'queued','photo_ids'=>$authorized]);GenerateMediaExport::dispatch($export->id)->afterCommit();return$this->reply($r,['uuid'=>$export->uuid,'state'=>'queued'],202);}private function allow(Request$r,MediaExport$e):void{abort_unless($e->user_id===$r->user()->id,403);}public function show(Request$r,MediaExport$export){$this->allow($r,$export);return response()->json($export);}public function cancel(Request$r,MediaExport$export){$this->allow($r,$export);abort_if($export->state==='completed',409);$export->update(['state'=>'cancelled','cancelled_at'=>now()]);return$this->reply($r,['state'=>'cancelled']);}public function download(Request$r,MediaExport$export,ProtectedMediaStorage$storage,CloudFrontUrlSigner$signer){$this->allow($r,$export);abort_unless($export->state==='completed'&&$export->expires_at?->isFuture(),410);if(config('media.delivery_driver')==='cloudfront')return redirect()->away($signer->sign($export->object_key,now()->addMinutes(5)));$stream=$storage->readStream($export->object_key);return response()->streamDownload(function()use($stream){fpassthru($stream);fclose($stream);},'lenspic-export.zip',['Content-Type'=>'application/zip','Cache-Control'=>'no-store, private']);}}
